// ---------------- txroot setter watcher (additive, non-invasive) ----------------
(function txrootSetterWatcher(){
  const g:any = (globalThis as any);
  g.__void_txroot_setter = g.__void_txroot_setter || {
    set_total: 0,
    mismatch_total: 0,
    errors_total: 0,
    heartbeat_total: 0,
    last_set_block: -1,
  };

  // If core2 counters exist, mirror them as a baseline (so Prom shows *something*)
  g.__void_txroot_core2 = g.__void_txroot_core2 || {
    saves_total: 0, set_total: 0, mismatch_total: 0, errors_total: 0, heartbeat_total: 0, last_set_block: -1,
  };

  // Small helper: fetch text/json without TSX "cache" option that caused TS errors earlier
  async function getText(u:string){
    try { const r = await fetch(u as any); return await r.text(); } catch { return null; }
  }
  async function getJSON(u:string){
    try { const r = await fetch(u as any); return await r.json(); } catch { return null; }
  }

  // Try a few known block endpoints in descending preference
  async function getBlockHeader(n:number): Promise<{txRoot?:string|null} | null> {
    const base = "";
    // full2 (newer), full (legacy), persisted (diag) — all additive shims in this repo
    const paths = [
      `/blocks/${n}/full2`,
      `/blocks/${n}/full`,
      `/blocks/${n}/persisted`
    ];
    for (const p of paths){
      const j = await getJSON(base + p);
      if (j && j.header) return j.header as any;
      if (j && j.ok && j.block && j.block.header) return j.block.header as any;
    }
    return null;
  }

  // Normalize 0x… vs hex string; accept empty-root constant too
  const EMPTY = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
  function norm(x:any): string | null {
    if (x == null) return null;
    const s = String(x).toLowerCase().replace(/^0x/,"");
    return s.length ? s : null;
  }

  // Heartbeat so Prom can see liveness on setter
  setInterval(()=>{ try { g.__void_txroot_setter.heartbeat_total++; } catch {} }, 2000);

  // Watch head; when a new block has a header.txRoot, bump counters once
  let lastChecked = -1;
  async function tick(){
    try {
      // Prefer in-process head if exported, else HTTP
      let head = -1;
      try {
        const t = await getText(`/head.txt`);
        const n = t ? parseInt(t.trim(), 10) : NaN;
        if (Number.isFinite(n)) head = n;
      } catch {}

      if (!Number.isFinite(head) || head < 0) return;

      if (head <= lastChecked) return;
      lastChecked = head;

      const hdr = await getBlockHeader(head);
      const txr = norm(hdr?.txRoot);
      if (txr){ // consider EMPTY as a valid root (0 tx)
        // Only advance if this head is newer than what we've recorded
        if (g.__void_txroot_setter.last_set_block < head){
          g.__void_txroot_setter.last_set_block = head;
          g.__void_txroot_setter.set_total++;
        }
      }
      // Mirror core2 if it’s ahead (keeps both exporters consistent)
      if (g.__void_txroot_core2.last_set_block > g.__void_txroot_setter.last_set_block){
        g.__void_txroot_setter.last_set_block = g.__void_txroot_core2.last_set_block;
      }
      if (g.__void_txroot_core2.set_total > g.__void_txroot_setter.set_total){
        g.__void_txroot_setter.set_total = g.__void_txroot_core2.set_total;
      }
    } catch {
      try { g.__void_txroot_setter.errors_total++; } catch {}
    }
  }
  setInterval(tick, 1000);
})();

// ---------------- txroot setter watcher V2 (absolute URLs, header endpoint) ----------------
(function txrootSetterWatcherV2(){
  const g:any = (globalThis as any);
  g.__void_txroot_setter = g.__void_txroot_setter || {
    set_total: 0, mismatch_total: 0, errors_total: 0, heartbeat_total: 0, last_set_block: -1,
  };

  const HOST = process.env.HTTP_HOST || "127.0.0.1";
  const PORT = process.env.HTTP_PORT || "4100";
  const BASE = `http://${HOST}:${PORT}`;

  async function getText(u:string){ try{ const r = await fetch(u as any); return await r.text(); } catch { return null; } }
  async function getJSON(u:string){ try{ const r = await fetch(u as any); return await r.json(); } catch { return null; } }

  function norm(x:any){ if (x==null) return null; return String(x).toLowerCase().replace(/^0x/,""); }

  setInterval(()=>{ try { g.__void_txroot_setter.heartbeat_total++; } catch {} }, 2000);

  let lastChecked = -1;
  async function tick(){
    try{
      // 1) head
      const t = await getText(`${BASE}/head.txt`);
      const head = t ? parseInt(t.trim(), 10) : NaN;
      if (!Number.isFinite(head) || head < 0) return;
      if (head <= lastChecked) return;
      lastChecked = head;

      // 2) ask inspector (it returns headerTxRoot/computedTxRoot/match)
      const insp:any = await getJSON(`${BASE}/__void/txroot/v4/header/${head}`);
      if (insp && insp.ok){
        const hx = norm(insp.headerTxRoot);
        if (hx){ // accept empty-root too; normalize
          if (g.__void_txroot_setter.last_set_block < head){
            g.__void_txroot_setter.last_set_block = head;
            g.__void_txroot_setter.set_total++;
          }
          return;
        }
      }

      // 3) fallback: try persisted/full shims
      const tries = [`${BASE}/blocks/${head}/full2`, `${BASE}/blocks/${head}/full`, `${BASE}/blocks/${head}/persisted`];
      for (const url of tries){
        const j:any = await getJSON(url);
        const hdr = j?.header || j?.block?.header;
        const root = hdr?.txRoot ?? hdr?.txroot ?? hdr?.txRootHex;
        const hx = norm(root);
        if (hx){
          if (g.__void_txroot_setter.last_set_block < head){
            g.__void_txroot_setter.last_set_block = head;
            g.__void_txroot_setter.set_total++;
          }
          return;
        }
      }
    }catch{ try { g.__void_txroot_setter.errors_total++; } catch {} }
  }
  setInterval(tick, 1000);
})();

// --- Additive: soft-gate dev & inspector routes w/o deleting anything ---
(function devRouteGate(){
  try {
    const appAny:any = (globalThis as any).__void_http_app || (globalThis as any).app;
    if (!appAny || typeof appAny.use !== 'function') return;

    const allow = process.env.VOID_DEV_ROUTES === '1';
    if (allow) return; // dev routes enabled

    // Block only well-known debug namespaces; core APIs unaffected
    const blocked = [
      "/__void",                // all our txroot shims/inspectors
      "/dev",                   // any dev inspectors
      "/tx/dev",                // tx burst helpers, raw inspectors
      "/metrics/drift6",        // follower drift exporter (dev)
      "/__void/metrics"         // ad-hoc prom text exporters
    ];

    appAny.use(blocked, (_req:any, res:any)=> res.status(404).end());
  } catch {}
})();
// --- SEALS_V3_BOOTSAFE_BEGIN ---
// Boot-safe seals exporter (head-derived, no dev shims). Idempotent re-mount.
// Exposes:
//   - /metrics/void/seals       (Prometheus text: last_number, last_ts_ms, rate_1m)
//   - /__void/seals/v3/status   (JSON diag)
(() => {
  const g:any = (globalThis as any);
  const app:any = g.__void_http_app || g.app;
  if (!app || typeof app.get !== "function") return;

  if (g.__void_seals_v3_bootsafe) return; // already mounted
  g.__void_seals_v3_bootsafe = true;

  const S:any = g.__void_seals_state = g.__void_seals_state || {
    lastNumber: -1,
    lastTsMs: 0,
    recent: [] as number[],
    polls: 0,
    lastErr: ""
  };

  function rate1m(): number {
    const cut = Date.now() - 60_000;
    S.recent = Array.isArray(S.recent) ? S.recent.filter((t:number)=>t>=cut) : [];
    return S.recent.length;
  }

  async function readLatestNumber(): Promise<number> {
    // Prefer in-process helpers if present
    try {
      const cand = [g.__void_node, g.node, g.__node, g.__VOID_NODE];
      for (const n of cand) {
        if (n && typeof n.getHeadNumber === "function") {
          const nnum = await n.getHeadNumber();
          if (Number.isFinite(nnum)) return nnum;
        }
        if (n && typeof n.headNumber === "number") {
          const nnum = n.headNumber;
          if (Number.isFinite(nnum)) return nnum;
        }
      }
    } catch {}

    // Fallback: local HTTP (/blocks/latest/number) or /head.txt
    const port = (process.env.HTTP_PORT || "4100").trim();
    const base = `http://127.0.0.1:${port}`;
    try {
      const r = await fetch(`${base}/blocks/latest/number`);
      if (r.ok) {
        const t = (await r.text()).trim();
        const n = parseInt(t, 10);
        if (Number.isFinite(n)) return n;
      }
    } catch (e:any) {
      S.lastErr = String(e?.message || e);
    }

    try {
      const r2 = await fetch(`${base}/head.txt`);
      if (r2.ok) {
        const t2 = (await r2.text()).trim();
        const n2 = parseInt(t2, 10);
        if (Number.isFinite(n2)) return n2;
      }
    } catch (e:any) {
      S.lastErr = String(e?.message || e);
    }

    return S.lastNumber;
  }

  async function tick() {
    S.polls++;
    try {
      const n = await readLatestNumber();
      if (Number.isFinite(n) && n > S.lastNumber) {
        S.lastNumber = n;
        S.lastTsMs = Date.now();
        S.recent = Array.isArray(S.recent) ? S.recent : [];
        S.recent.push(S.lastTsMs);
      }
    } catch (e:any) {
      S.lastErr = String(e?.message || e);
    }
  }

  // Start a single poller (idempotent)
  if (!g.__void_seals_v3_timer) {
    g.__void_seals_v3_timer = setInterval(tick, 2000);
    setTimeout(tick, 250); // first kick shortly after boot
  }

  // Prom text
  app.get("/metrics/void/seals", (_req:any, res:any) => {
    // keep recent window fresh even if Prom is the only traffic
    rate1m();
    res.type("text/plain; version=0.0.4");
    res.send(
`# HELP void_seal_last_number Latest sealed block number
# TYPE void_seal_last_number gauge
void_seal_last_number ${S.lastNumber}
# HELP void_seal_last_ts_ms Timestamp (ms) of last seal observed
# TYPE void_seal_last_ts_ms gauge
void_seal_last_ts_ms ${S.lastTsMs}
# HELP void_seal_rate_1m Seals observed in the last 60 seconds
# TYPE void_seal_rate_1m gauge
void_seal_rate_1m ${rate1m()}
`);
  });

  // JSON diag
  app.get("/__void/seals/v3/status", (_req:any, res:any) => {
    res.json({
      mounted: { bootsafe: true },
      lastNumber: S.lastNumber,
      lastTsMs: S.lastTsMs,
      rate1m: rate1m(),
      polls: S.polls,
      lastErr: S.lastErr || null
    });
  });
})();
// --- SEALS_V3_BOOTSAFE_END ---
// --- SEALS_V3_WATCHDOG_BEGIN ---
// Seals V3 watchdog: auto-remount /metrics/void/seals and /__void/seals/v3/status
// if the Express app is replaced or routes disappear.
(() => {
  const g:any = (globalThis as any);
  const getApp = () => g.__void_http_app || g.app;
  const PATH_METRICS = "/metrics/void/seals";
  const PATH_DIAG    = "/__void/seals/v3/status";

  // Shared state used by bootsafe block if present; create if missing.
  g.__void_seals_state = g.__void_seals_state || {
    lastNumber: -1,
    lastTsMs: 0,
    recent: [] as number[],
    polls: 0,
    lastErr: ""
  };
  const S:any = g.__void_seals_state;

  function rate1m(): number {
    const cut = Date.now() - 60_000;
    S.recent = Array.isArray(S.recent) ? S.recent.filter((t:number)=>t>=cut) : [];
    return S.recent.length;
  }

  function hasRoute(app:any, path:string): boolean {
    try {
      const st = app?._router?.stack || [];
      return st.some((l:any) => (l?.route?.path === path) || (l?.regexp && String(l.regexp).includes(path)));
    } catch { return false; }
  }

  function mount(app:any) {
    if (!app || typeof app.get !== "function") return false;

    // (Re)register metrics
    if (!hasRoute(app, PATH_METRICS)) {
      app.get(PATH_METRICS, (_req:any, res:any) => {
        rate1m(); // keep window fresh
        res.type("text/plain; version=0.0.4");
        res.send(
`# HELP void_seal_last_number Latest sealed block number
# TYPE void_seal_last_number gauge
void_seal_last_number ${S.lastNumber}
# HELP void_seal_last_ts_ms Timestamp (ms) of last seal observed
# TYPE void_seal_last_ts_ms gauge
void_seal_last_ts_ms ${S.lastTsMs}
# HELP void_seal_rate_1m Seals observed in the last 60 seconds
# TYPE void_seal_rate_1m gauge
void_seal_rate_1m ${rate1m()}
`);
      });
    }

    // (Re)register diag
    if (!hasRoute(app, PATH_DIAG)) {
      app.get(PATH_DIAG, (_req:any, res:any) => {
        res.json({
          mounted: { watchdog: true },
          lastNumber: S.lastNumber,
          lastTsMs: S.lastTsMs,
          rate1m: rate1m(),
          polls: S.polls,
          lastErr: S.lastErr || null
        });
      });
    }
    return true;
  }

  // Remember last seen app to detect swaps
  let lastApp:any = null;

  function tickWatchdog() {
    const app = getApp();
    if (!app) return;
    if (app !== lastApp || !hasRoute(app, PATH_METRICS) || !hasRoute(app, PATH_DIAG)) {
      mount(app);
      lastApp = app;
    }
  }

  // Start watchdog (idempotent)
  if (!g.__void_seals_watchdog_timer) {
    g.__void_seals_watchdog_timer = setInterval(tickWatchdog, 1000);
    setTimeout(tickWatchdog, 200); // early pass
  }
})();
// --- SEALS_V3_WATCHDOG_END ---
// --- SEALS_V3_POLLER_BEGIN ---
// Seals V3 poller: updates shared state by reading current head periodically.
// Works with the watchdog + bootsafe blocks. Idempotent.
(() => {
  const g:any = (globalThis as any);

  // Shared state (created if missing)
  g.__void_seals_state = g.__void_seals_state || {
    lastNumber: -1,
    lastTsMs: 0,
    recent: [] as number[],
    polls: 0,
    lastErr: ""
  };
  const S:any = g.__void_seals_state;

  // Try several fast/local sources to read the latest head number.
  async function readHead(): Promise<number> {
    // 1) In-process globals if present
    try {
      const cand = [g.__void_node, g.node, g.__node, g.__VOID_NODE];
      for (const n of cand) {
        if (!n) continue;
        // common shapes we've used:
        //   n.headNumber  OR  n.head?.number  OR  n.store?.heads?.head
        const v = (n.headNumber ?? n.head?.number ?? n.store?.heads?.head);
        if (Number.isFinite(v)) return v;
      }
    } catch {}

    // 2) Lightweight local HTTP: /head.txt -> /blocks/latest/number
    const port = (process.env.HTTP_PORT || "4100").trim();
    const tryFetchNum = async (url:string) => {
      const r = await fetch(url).catch(()=>null);
      if (!r || !r.ok) return null;
      const t = await r.text();
      const n = parseInt((t||"").trim(), 10);
      return Number.isFinite(n) ? n : null;
    };

    const a = await tryFetchNum(`http://127.0.0.1:${port}/head.txt`);
    if (a !== null) return a;

    const b = await tryFetchNum(`http://127.0.0.1:${port}/blocks/latest/number`);
    if (b !== null) return b;

    return S.lastNumber; // fallback (no change)
  }

  function trimRecent(now:number) {
    const cut = now - 60_000;
    S.recent = Array.isArray(S.recent) ? S.recent.filter((t:number)=>t>=cut) : [];
  }

  async function tick() {
    S.polls = (S.polls|0) + 1;
    try {
      const n = await readHead();
      if (Number.isFinite(n) && n > S.lastNumber) {
        const now = Date.now();
        S.lastNumber = n;
        S.lastTsMs   = now;
        trimRecent(now);
        S.recent.push(now);
        if (S.recent.length > 600) S.recent.splice(0, S.recent.length - 600); // cap
        S.lastErr = "";
      }
    } catch (e:any) {
      S.lastErr = (e?.message || String(e)).slice(0, 200);
    }
  }

  if (!g.__void_seals_poller_timer) {
    // quick priming passes, then steady every 1s
    tick(); setTimeout(tick, 200); setTimeout(tick, 800);
    g.__void_seals_poller_timer = setInterval(tick, 1000);
  }
})();
// --- SEALS_V3_POLLER_END ---
// --- SEALS_V3_HEARTBEAT_FIX_BEGIN ---
// Seals v3 heartbeat: minimal poller that updates lastTsMs when head advances.
// Safe to coexist with the main poller; does nothing if already running.
(() => {
  const g:any = (globalThis as any);
  if (g.__void_seals_v3_heartbeat) return;
  g.__void_seals_v3_heartbeat = true;

  // Shared state with bootsafe/watchdog/poller
  g.__void_seals_state = g.__void_seals_state || {
    lastNumber: -1, lastTsMs: 0, recent: [] as number[], polls: 0, lastErr: ""
  };
  const S:any = g.__void_seals_state;

  async function readHeadNumber(): Promise<number> {
    try {
      const cand = [g.__void_node, g.node, g.__node, g.__VOID_NODE];
      for (const n of cand) {
        if (!n) continue;
        const v = (n.headNumber ?? n.head?.number ?? n.store?.heads?.head);
        if (Number.isFinite(v)) return v;
      }
    } catch {}
    try {
      const port = (process.env.HTTP_PORT || "4100").trim();
      const tryNum = async (u:string) => {
        const r = await fetch(u).catch(()=>null); if (!r?.ok) return NaN;
        const t = (await r.text()).trim(); const n = parseInt(t, 10);
        return Number.isFinite(n) ? n : NaN;
      };
      let n = await tryNum(`http://127.0.0.1:${port}/head.txt`);
      if (!Number.isFinite(n)) n = await tryNum(`http://127.0.0.1:${port}/blocks/latest/number`);
      return Number.isFinite(n) ? n : S.lastNumber;
    } catch { return S.lastNumber; }
  }

  function pushRecent(ts:number){ 
    const cut = Date.now() - 60_000;
    S.recent = Array.isArray(S.recent) ? S.recent.filter((t:number)=>t>=cut) : [];
    S.recent.push(ts);
  }

  async function tick(){
    try {
      const n = await readHeadNumber();
      S.polls = (S.polls|0) + 1;
      if (Number.isFinite(n) && n >= 0 && n !== S.lastNumber) {
        S.lastNumber = n;
        S.lastTsMs = Date.now();
        pushRecent(S.lastTsMs);
      }
    } catch(e:any){ S.lastErr = String(e?.message||e); }
  }

  // Start fast at boot, then steady every 5s
  tick();
  setInterval(tick, 5000).unref?.();
})();
/// --- SEALS_V3_HEARTBEAT_FIX_END ---
// --- SEALS_V3_HEALTH_WATCHDOG_BEGIN ---
// Watches the Express app and (re)mounts /metrics/void/seals/health reliably.
(() => {
  const g:any = (globalThis as any);
  const getApp = () => g.__void_http_app || g.app;
  const PATH_HEALTH = "/metrics/void/seals/health";

  // Share state with seals v3 blocks
  g.__void_seals_state = g.__void_seals_state || {
    lastNumber: -1, lastTsMs: 0, recent: [] as number[], polls: 0, lastErr: ""
  };
  const S:any = g.__void_seals_state;

  function hasRoute(app:any, path:string): boolean {
    try {
      const st = app?._router?.stack || [];
      return st.some((l:any) => (l?.route?.path === path) || (l?.regexp && String(l.regexp).includes(path)));
    } catch { return false; }
  }

  function mount(app:any){
    if (!app || typeof app.get !== "function") return false;
    if (hasRoute(app, PATH_HEALTH)) return true;

    app.get(PATH_HEALTH, (req:any, res:any) => {
      const fresh = Number.isFinite(S.lastTsMs) ? (Date.now() - S.lastTsMs < 120_000) : false;
      const ok = (S.lastNumber>=0) && fresh;
      if ((req.query?.format||"") === "prom") {
        res.type("text/plain").send(
          "# HELP void_seals_health 1=healthy, 0=stalled\n" +
          "# TYPE void_seals_health gauge\n" +
          `void_seals_health ${ok?1:0}\n`
        );
      } else {
        res.json({ ok, lastNumber:S.lastNumber??-1, lastTsMs:S.lastTsMs??0 });
      }
    });
    return true;
  }

  // Try now, then keep it alive
  mount(getApp());
  setInterval(() => { mount(getApp()); }, 2000);
})();
/// --- SEALS_V3_HEALTH_WATCHDOG_END ---

// ===================== txRoot Header-Setter Shim v2 (additive) =====================
(function txrootHeaderSetterShimV2(){
  const BOOT_TAG = "[txroot/header-shim:v2]";
  let attached = false;
  // in-memory header map (number -> { txRoot, ts })
  const headerMap = new Map<number, { txRoot: string; ts: number }>();
  // counters
  let set_total = 0, mismatch_total = 0, errors_total = 0, heartbeat_total = 0;
  let last_set_block = -1;

  function env(k: string, d: string) { return (process.env[k] ?? d); }
  const HTTP_PORT = parseInt(env("HTTP_PORT", "4100"), 10);
  const BASE = `http://127.0.0.1:${HTTP_PORT}`;

  function getApp(): any {
    return (globalThis as any).__void_http_app || (globalThis as any).app || undefined;
  }

  async function httpJSON(url: string): Promise<any> {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
    return res.json();
  }

  async function computeTxRoot(n: number): Promise<string> {
    // Uses existing dev endpoint that returns { ok, number, root, leaves }
    const j = await httpJSON(`${BASE}/dev/txroot/${n}`);
    if (!j || j.ok !== true || typeof j.root !== "string") {
      throw new Error(`txroot endpoint unexpected for #${n}`);
    }
    return j.root as string;
  }

  async function getLatestNumber(): Promise<number> {
    const res = await fetch(`${BASE}/blocks/latest/number`);
    if (!res.ok) throw new Error(`latest/number HTTP ${res.status}`);
    const text = await res.text();
    const n = parseInt(text, 10);
    if (!Number.isFinite(n)) throw new Error(`bad latest number: ${text}`);
    return n;
  }

  function promLine(name: string, help: string, type: "counter" | "gauge", val: string | number) {
    return `# HELP ${name} ${help}\n# TYPE ${name} ${type}\n${name} ${val}\n`;
  }

  // exporter
  function installMetricsExporter(app: any){
    const path = "/__void/metrics/txroot4/setter.prom";
    if ((app as any)._txroot_setter_v2_metrics_bound) return;
    app.get(path, (_req: any, res: any) => {
      heartbeat_total++;
      let out = "";
      out += promLine("void_txroot_header_set_total", "Header txRoot sets performed", "counter", set_total);
      out += promLine("void_txroot_header_mismatch_total", "Header txRoot mismatches detected (pre-normalization)", "counter", mismatch_total);
      out += promLine("void_txroot_header_errors_total", "Errors while setting txRoot", "counter", errors_total);
      out += promLine("void_txroot_header_last_set_block", "Last block number where txRoot was set", "gauge", last_set_block);
      out += promLine("void_txroot_header_heartbeat_total", "Heartbeat to signal liveness of setter", "counter", heartbeat_total);
      res.type("text/plain").send(out);
    });
    (app as any)._txroot_setter_v2_metrics_bound = true;
    console.log(BOOT_TAG, "metrics bound at", path);
  }

  // read-only header view with txRoot (doesn't overwrite disk)
  function installHeaderView(app: any){
    if ((app as any)._txroot_setter_v2_header_bound) return;
    app.get("/blocks/:n/header2", async (req: any, res: any) => {
      const n = parseInt(req.params.n, 10);
      if (!Number.isFinite(n)) return res.status(400).json({ ok:false, error:"bad number" });
      const m = headerMap.get(n);
      if (!m) return res.json({}); // unknown yet — allow caller to retry
      return res.json({ number: n, txRoot: m.txRoot, timestamp_ms: m.ts });
    });
    (app as any)._txroot_setter_v2_header_bound = true;
    console.log(BOOT_TAG, "header view bound at /blocks/:n/header2");
  }

  async function processNewBlocks(latest: number, fromIncl: number){
    for (let n = Math.max(0, fromIncl); n <= latest; n++){
      if (headerMap.has(n)) continue;
      try {
        const root = await computeTxRoot(n);
        headerMap.set(n, { txRoot: root, ts: Date.now() });
        set_total++;
        last_set_block = n;
      } catch (e:any) {
        errors_total++;
        // no throw; keep loop resilient
      }
    }
  }

  function startPoller(app: any){
    if ((app as any)._txroot_setter_v2_poller) return;
    let lastSeen = -1;
    let tickBusy = false;
    const interval = setInterval(async ()=>{
      if (tickBusy) return;
      tickBusy = true;
      try {
        const latest = await getLatestNumber();
        if (latest > lastSeen){
          await processNewBlocks(latest, lastSeen + 1);
          lastSeen = latest;
        }
      } catch (e:any) {
        // swallow errors; exporter will still heartbeat
      } finally {
        tickBusy = false;
      }
    }, 1000);
    (app as any)._txroot_setter_v2_poller = interval;
    console.log(BOOT_TAG, "poller started (1s)");
  }

  // bootsafe attach
  (function attachSoon(){
    const app = getApp();
    if (!app || typeof app.get !== "function") {
      return setTimeout(attachSoon, 300);
    }
    if (attached) return;
    attached = true;
    installMetricsExporter(app);
    installHeaderView(app);
    startPoller(app);
    console.log(BOOT_TAG, "attached");
  })();

})();
 // =================== /txRoot Header-Setter Shim v2 (additive) =====================

// ===================== txRoot Header-Setter Sidecar v3 (additive) =====================
(function txrootHeaderSetterSidecarV3(){
  const TAG = "[txroot/header-sidecar:v3]";
  let attached = false;

  // counters
  let set_total = 0, mismatch_total = 0, errors_total = 0, heartbeat_total = 0;
  let last_set_block = -1;

  function env(k: string, d: string) { return (process.env[k] ?? d); }
  const HTTP_PORT = parseInt(env("HTTP_PORT", "4100"), 10);
  const BASE = `http://127.0.0.1:${HTTP_PORT}`;

  function getApp(): any {
    return (globalThis as any).__void_http_app || (globalThis as any).app || undefined;
  }

  async function httpText(url: string): Promise<string> {
    const r = await fetch(url);
    if (!r.ok) throw new Error(`HTTP ${r.status} ${url}`);
    return r.text();
  }
  async function httpJSON(url: string): Promise<any> {
    const r = await fetch(url);
    if (!r.ok) throw new Error(`HTTP ${r.status} ${url}`);
    return r.json();
  }

  async function getHeadNumber(): Promise<number> {
    // Use ultra-stable /head.txt first; fallback to /blocks/latest/number
    try {
      const t = await httpText(`${BASE}/head.txt`);
      const n = parseInt(t.trim(), 10);
      if (Number.isFinite(n)) return n;
    } catch {}
    const t2 = await httpText(`${BASE}/blocks/latest/number`);
    const n2 = parseInt(t2.trim(), 10);
    if (!Number.isFinite(n2)) throw new Error(`bad latest number: ${t2}`);
    return n2;
  }

  async function computeTxRoot(n: number): Promise<string> {
    const j = await httpJSON(`${BASE}/dev/txroot/${n}`);
    if (!j || j.ok !== true || typeof j.root !== "string") {
      throw new Error(`/dev/txroot/${n} unexpected`);
    }
    return j.root as string;
  }

  function promLine(name: string, help: string, type: "counter"|"gauge", val: string|number) {
    return `# HELP ${name} ${help}\n# TYPE ${name} ${type}\n${name} ${val}\n`;
  }

  function bindExporter(app:any){
    const path = "/__void/metrics/txroot4/setter2.prom";
    if ((app as any)._txroot_setter_v3_metrics_bound) return;
    app.get(path, (_req:any, res:any) => {
      heartbeat_total++;
      let out = "";
      out += promLine("void_txroot_header_set_total", "Header txRoot sets performed", "counter", set_total);
      out += promLine("void_txroot_header_mismatch_total", "Header txRoot mismatches detected (pre-normalization)", "counter", mismatch_total);
      out += promLine("void_txroot_header_errors_total", "Errors while setting txRoot", "counter", errors_total);
      out += promLine("void_txroot_header_last_set_block", "Last block number where txRoot was set", "gauge", last_set_block);
      out += promLine("void_txroot_header_heartbeat_total", "Heartbeat to signal liveness of setter", "counter", heartbeat_total);
      res.type("text/plain").send(out);
    });
    (app as any)._txroot_setter_v3_metrics_bound = true;
    console.log(TAG, "metrics bound at", path);
  }

  function startPoller(app:any){
    if ((app as any)._txroot_setter_v3_poller) return;
    let tickBusy = false;
    let lastSeen = -1;

    const interval = setInterval(async () => {
      if (tickBusy) return;
      tickBusy = true;
      try {
        const head = await getHeadNumber();            // robust source of truth
        if (head > lastSeen) {
          // Only process the latest (or a small catch-up window)
          const start = Math.max(lastSeen + 1, head - 4);
          for (let n = start; n <= head; n++) {
            try {
              const root = await computeTxRoot(n);
              // NOTE: read-only path (no disk writes here)
              set_total++;
              last_set_block = n;
            } catch (e:any) {
              errors_total++;
            }
          }
          lastSeen = head;
        }
      } catch (e:any) {
        errors_total++;
      } finally {
        tickBusy = false;
      }
    }, 1000);
    (app as any)._txroot_setter_v3_poller = interval;
    console.log(TAG, "poller started (1s, /head.txt primary)");
  }

  (function attachSoon(){
    const app = getApp();
    if (!app || typeof app.get !== "function") return setTimeout(attachSoon, 300);
    if (attached) return;
    attached = true;
    bindExporter(app);
    startPoller(app);
    console.log(TAG, "attached");
  })();
})();
