// ---------------- Liveness TX shim v2 (SAFEBOOT-friendly, additive) ----------------
(function LivenessTxShimV2(){
  const ENABLED = (process.env.VOID_LIVENESS_TX ?? process.env.LIVENESS_TX ?? "0") === "1";
  if (!ENABLED) return;

  const PORT = Number(process.env.HTTP_PORT || 4100);
  const URL_BASE = `http://127.0.0.1:${PORT}`;

  const TICK_MS    = Math.max(1000, Number(process.env.PROPOSER_TICK_MS || 2000));
  const STALL_MS   = Math.max(2*TICK_MS + 500, Number(process.env.LIVENESS_STALL_MS || (2*TICK_MS + 500)));
  const MIN_GAP_MS = Math.max(TICK_MS, Number(process.env.LIVENESS_MIN_GAP_MS || 6000));

  // Optional hard cap: submits/min (defaults modestly)
  const MAX_PER_MIN = Math.max(1, Number(process.env.LIVENESS_MAX_PER_MIN || 6));

  // Shared state (coexists with your existing exporter)
  const LNSYM = "__void_liveness";
  const state = (globalThis as any)[LNSYM] = (globalThis as any)[LNSYM] || {
    _lastSubmitMs: 0, _submits: 0,
    bump(){ this._lastSubmitMs = Date.now(); this._submits++; },
    reads(){ return { lastSubmitMs: this._lastSubmitMs, submits: this._submits }; }
  };

  let lastHead = -1;
  let lastHeadAt = Date.now();
  let recent = [] as number[]; // submit timestamps (ms)

  async function getHead(): Promise<number> {
    try {
      const r = await fetch(`${URL_BASE}/head.txt`, { cache: "no-store" });
      const t = await r.text();
      const n = Number(String(t).trim().split(/\s+/)[0]);
      return Number.isFinite(n) ? n : -1;
    } catch { return -1; }
  }

  async function getMempoolSize(): Promise<number> {
    try {
      const r = await fetch(`${URL_BASE}/mempool/global/size.json`, { cache: "no-store" });
      const j:any = await r.json();
      return Number(j?.size ?? 0);
    } catch { return 0; }
  }

  function rateWindowOk(now:number): boolean {
    recent = recent.filter(ms => now - ms < 60_000);
    return recent.length < MAX_PER_MIN;
  }

  async function submitTinyTx(): Promise<boolean> {
    try {
      const payload = Buffer.from(`live:${Date.now()}`).toString("hex");
      const r = await fetch(`${URL_BASE}/tx/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ data: `0x${payload}` })
      });
      if (!r.ok) return false;
      state.bump();
      recent.push(Date.now());
      return true;
    } catch { return false; }
  }

  async function tick(){
    try {
      const now = Date.now();
      const head = await getHead();
      if (head >= 0) {
        if (head !== lastHead) { lastHead = head; lastHeadAt = now; }
      }
      const stalled = (now - lastHeadAt) >= STALL_MS;
      const mp = await getMempoolSize();
      const canSubmit = (now - state._lastSubmitMs) >= MIN_GAP_MS && rateWindowOk(now);

      if (stalled && mp === 0 && canSubmit) {
        await submitTinyTx(); // ignore result; exporter will reflect success
      }
    } catch { /* ignore */ }
    setTimeout(tick, TICK_MS);
  }

  setTimeout(tick, TICK_MS);
})();

// ---------------- Agent Receipts Prom Exporter (additive, no deps) -----------------
(function voidAgentReceiptsExporter(){
  const TICK=400;
  let attached=false;
  function getApp(){ return (globalThis as any).__void_http_app || (globalThis as any).app; }

  // simple counters + freshness
  let total=0, ok=0, err=0, lastOkTs=0, lastAnyTs=0;

  function mount(){
    const app:any = getApp();
    if (!app || typeof app.use!=="function") return setTimeout(mount, TICK);
    if (attached) return; attached=true;

    // count results of /agent/v0/receipt/:id POSTs without touching core handlers
    app.use((req:any, res:any, next:any)=>{
      const isReceipt = req.method==="POST" && /^\/agent\/v0\/receipt(\/|$)/.test(req.path || "");
      if (!isReceipt) return next();
      total++;
      res.on("finish", ()=>{
        lastAnyTs = Date.now();
        if (res.statusCode>=200 && res.statusCode<300){ ok++; lastOkTs = Date.now(); }
        else { err++; }
      });
      next();
    });

    function prom(){
      const now = Date.now();
      const freshSec = 60; // coverage window
      const coverage = (lastOkTs && ((now - lastOkTs) <= freshSec*1000)) ? 1 : 0;
      const lines = [
        "# HELP void_agent_receipts_total Total receipt POST attempts",
        "# TYPE void_agent_receipts_total counter",
        `void_agent_receipts_total ${total}`,
        "# HELP void_agent_receipts_ok_total Successful receipt posts",
        "# TYPE void_agent_receipts_ok_total counter",
        `void_agent_receipts_ok_total ${ok}`,
        "# HELP void_agent_receipts_err_total Failed receipt posts",
        "# TYPE void_agent_receipts_err_total counter",
        `void_agent_receipts_err_total ${err}`,
        "# HELP void_agent_receipts_coverage 1 if a success occurred in the last 60s",
        "# TYPE void_agent_receipts_coverage gauge",
        `void_agent_receipts_coverage ${coverage}`,
        "# HELP void_agent_receipts_last_ok_ts_ms Last successful post timestamp (ms)",
        "# TYPE void_agent_receipts_last_ok_ts_ms gauge",
        `void_agent_receipts_last_ok_ts_ms ${lastOkTs||0}`,
        "# HELP void_agent_receipts_last_any_ts_ms Last post attempt timestamp (ms)",
        "# TYPE void_agent_receipts_last_any_ts_ms gauge",
        `void_agent_receipts_last_any_ts_ms ${lastAnyTs||0}`,
      ];
      return lines.join("\n")+"\n";
    }

    // exporter routes
    app.get("/__void/metrics/agent/receipts.prom", (req:any,res:any)=>{
      res.setHeader("content-type","text/plain; version=0.0.4");
      res.end(prom());
    });
    // alias for convenience
    app.get("/__void/metrics/agent/receipts", (req:any,res:any)=>{
      res.setHeader("content-type","text/plain; version=0.0.4");
      res.end(prom());
    });
  }
  mount();
})();

